{"command":"python3 -c "
import csv

# Verify stop_times.csv
with open('outputs/t05_clean_stop_times.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    rows = list(reader)

print(f'Total rows: {len(rows)}')
print()

# Check for times beyond 24:00:00
times_over_24 = []
for r in rows:
    arrival = r['arrival_time']
    departure = r['departure_time']
    if arrival and arrival > '24:00:00':
        times_over_24.append((arrival, r['stop_id']))
    if departure and departure > '24:00:00':
        times_over_24.append((departure, r['stop_id']))

if times_over_24:
    print('Times beyond 24:00:00:')
    for t, sid in times_over_24:
        print(f'  {t} for stop {sid}')
else:
    print('No times beyond 24:00:00 found')

# Check for stop_ids not in clean_stops
with open('outputs/t05_clean_stops.csv', 'r', encoding='utf-8') as f:
    stops = set(r['stop_id'] for r in csv.DictReader(f))

invalid_stop_ids = set()
for r in rows:
    if r['stop_id'] not in stops:
        invalid_stop_ids.add(r['stop_id'])

if invalid_stop_ids:
    print(f'Invalid stop_ids in stop_times: {invalid_stop_ids}')
else:
    print('All stop_ids in stop_times are valid')
